#!/usr/bin/env node
/**
 * Inject the shared ProjectBay feedback widget into every built HTML page.
 *
 * dist/ is regenerated by every build (and is gitignored), so the tag cannot
 * live only in the served output — this runs as part of `npm run build`, right
 * after the localized pages are generated, and is idempotent.
 *
 * The widget identifies the site from the subdomain, so no data-site is needed.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DIST_DIR = path.resolve(__dirname, '../dist');

const WIDGET_SRC = 'https://feedback.projectbay.uk/feedback.js';
const TAG = `<script defer src="${WIDGET_SRC}"></script>`;
const SKIP_DIRS = new Set(['pdfjs-viewer', 'pdfjs-annotation-viewer', 'docs']);

function listHtml(dir, prefix = '') {
  const out = [];
  for (const entry of fs.readdirSync(dir)) {
    const full = path.join(dir, entry);
    const rel = path.posix.join(prefix, entry);
    if (fs.statSync(full).isDirectory()) {
      if (SKIP_DIRS.has(entry) || entry.startsWith('.')) continue;
      out.push(...listHtml(full, rel));
    } else if (entry.endsWith('.html')) {
      out.push({ full, rel });
    }
  }
  return out;
}

if (!fs.existsSync(DIST_DIR)) {
  console.error('❌ inject-feedback-widget: dist/ not found');
  process.exit(1);
}

const files = listHtml(DIST_DIR);
let injected = 0;
let present = 0;
let skipped = 0;

for (const file of files) {
  const html = fs.readFileSync(file.full, 'utf-8');
  if (html.includes(WIDGET_SRC)) {
    present++;
    continue;
  }
  const bodyClose = html.lastIndexOf('</body>');
  if (bodyClose === -1) {
    skipped++;
    console.warn(`   [skip] ${file.rel}: no </body>`);
    continue;
  }
  fs.writeFileSync(
    file.full,
    `${html.slice(0, bodyClose)}${TAG}\n${html.slice(bodyClose)}`
  );
  injected++;
}

console.log(
  `💬 feedback widget: ${injected} injected, ${present} already present, ${skipped} skipped (${files.length} HTML files)`
);
